public class AudioTranscriber : MonoBehaviour
{
    [Tooltip("Path to the audio file on your device")]
    public string audioFilePath;

    [Tooltip("URL of the FastAPI /transcribe endpoint")]
    public string apiUrl = "http://yourserver.com/transcribe";

    public TMP_InputField transcriptionField;

    // Use this function to start the transcription process
    public void StartTranscription()
    {
        if (string.IsNullOrEmpty(audioFilePath))
        {
            Debug.LogError("Audio file path is empty.");
            return;
        }

        if (!File.Exists(audioFilePath))
        {
            Debug.LogError("Audio file does not exist: " + audioFilePath);
            return;
        }

        StartCoroutine(UploadAndTranscribeCoroutine(audioFilePath));
    }

    private IEnumerator UploadAndTranscribeCoroutine(string path)
    {
        // Read the audio file as bytes
        byte[] audioData = File.ReadAllBytes(path);

        if (audioData == null || audioData.Length == 0)
        {
            Debug.LogError("Failed to read audio data from the file.");
            yield break;
        }

        // Construct the multipart form data
        List<IMultipartFormSection> formData = new List<IMultipartFormSection>();

        // Add the audio file with the field name "file"
        formData.Add(new MultipartFormFileSection(
            "file",
            audioData,
            Path.GetFileName(path),
            "audio/wav" ));

        // Add the task parameter needed for the FastAPI endpoint
        formData.Add(new MultipartFormDataSection("task", "transcribe"));

        // Send the request to the server
        using (UnityWebRequest www = UnityWebRequest.Post(apiUrl, formData))
        {
            // Set a timeout to be able to wait for the transcription to complete
            www.timeout = 60;

            yield return www.SendWebRequest();

#if UNITY_2020_1_OR_NEWER
            if (www.result == UnityWebRequest.Result.ConnectionError ||
                www.result == UnityWebRequest.Result.ProtocolError)
#else
            if (www.isNetworkError || www.isHttpError)
#endif
            {
                Debug.LogError($"Error uploading audio: {www.error}");
            }
            else
            {
                // Parse the JSON response
                Debug.Log("Response: " + www.downloadHandler.text);

                try
                {
                    TranscriptionResponse response = JsonUtility.FromJson<TranscriptionResponse>(www.downloadHandler.text);

                    if (response != null)
                    {
                        Debug.Log("Transcription: " + response.text);

                        if (transcriptionField == null)
                        {
                            Debug.LogWarning("Set the transcription output text field in the Unity Inspector!");
                        }
                        else
                        {
                            transcriptionField.text = response.text;
                        }
                    }
                    else
                    {
                        Debug.LogError("Failed to parse JSON response.");
                    }
                }
                catch (System.Exception ex)
                {
                    Debug.LogError($"Error parsing JSON response: {ex.Message}");
                }
            }
        }
    }
}

